"""
From records to the bid: which record applies is decided here by the bid rules, in code; `calc` does the arithmetic.

Everything in this module is pure. It never fails as a whole: a fact that is missing or unreadable costs the
fields that depend on it and is written to `Plan.notes`, the rest of the bid is still priced.
"""
import re
from dataclasses import dataclass, field
from datetime import date, datetime
from decimal import Decimal

import calc
import evidence
import parse
from pydantic import BaseModel, Field

NUMERIC = ("bore", "stroke", "pressure")


# ---------------------------------------------------------------- tender, clarifications, specification


@dataclass
class Line:
    """One tender position with what the tender, its clarifications and the specification say about it."""

    position: str
    quantity: int | None = None  # final quantity in the stated unit
    unit: calc.Unit = calc.Unit.PIECE
    requirement: evidence.Requirement | None = None
    attributes: dict[str, str] = field(default_factory=dict)  # the five match attributes after amendments, as written
    keys: dict[str, str] = field(default_factory=dict)  # assignment kind -> value from the clarifications

    @property
    def group(self) -> str:
        return self.requirement.catalogue_group.strip() if self.requirement else ""

    @property
    def pieces(self) -> int | None:
        if self.quantity is None:
            return None
        per_set = None
        if self.requirement and self.requirement.pieces_per_set:
            try:
                per_set = parse.whole(self.requirement.pieces_per_set)
            except parse.ParseError:
                per_set = None
        try:
            return calc.to_pieces(self.quantity, self.unit, per_set)
        except calc.CalcError:
            return None


def _canonical(written: str, known: list[str]) -> str:
    """The entry of `known` that `written` means, else `written` itself."""
    for candidate in known:
        if parse.same_label(written, candidate):
            return candidate
    return written.strip()


def _dated(answers: list[evidence.Clarification], scenario: date, notes: list[str]
           ) -> list[tuple[datetime, evidence.Clarification]]:
    """The answers given no later than the scenario date, oldest first."""
    dated = []
    for answer in answers:
        try:
            given = parse.when(answer.date, scenario.year)
        except parse.ParseError:
            notes.append(f"clarification {answer.number}: date {answer.date!r} not readable, ignored")
            continue
        if given.date() <= scenario:
            dated.append((given, answer))
    return sorted(dated, key=lambda pair: (pair[0], calc.position_key(pair[1].number)))


def lines(sheet: evidence.TenderSheet, clarifications: evidence.Clarifications | None,
          spec: evidence.SpecSheet | None, scenario: date, notes: list[str]) -> list[Line]:
    """Rules 1, 2, 13, 14 and 17: final quantities, the governing requirement with its amendments, and the keys."""
    positions = [p.position.strip() for p in sheet.positions]
    requirements = spec.requirements if spec else []
    dated = _dated(clarifications.answers, scenario, notes) if clarifications else []
    numbers = [answer.number for _, answer in dated]
    withdrawn = {_canonical(w, numbers) for _, answer in dated for w in answer.withdraws}

    changes, amendments = [], []
    for given, answer in dated:
        for change in answer.quantity_changes:
            try:
                changes.append(calc.QuantityChange(number=answer.number, date=given, quantity=parse.whole(change.quantity),
                                                   position=_canonical(change.position, positions)))
            except parse.ParseError:
                notes.append(f"clarification {answer.number}: quantity {change.quantity!r} not readable")
        for amendment in answer.amendments:
            if amendment.attribute in calc.MATCH_KEYS and spec:
                amendments.append(calc.Amendment(
                    date=given, revision=_canonical(amendment.revision, [spec.revision]),
                    requirement=_canonical(amendment.requirement, [r.requirement for r in requirements]),
                    attributes={amendment.attribute: amendment.value}))

    result = []
    for tender in sheet.positions:
        line = Line(position=tender.position.strip())
        try:
            line.unit = calc.parse_unit(tender.unit)
        except calc.CalcError:
            notes.append(f"{line.position}: unit {tender.unit!r} unknown, taken as pieces")
        try:
            line.quantity = calc.resolve_quantity(parse.whole(tender.quantity), line.position, changes, withdrawn,
                                                  scenario)
        except parse.ParseError:
            notes.append(f"{line.position}: quantity {tender.quantity!r} not readable")
        for candidate in requirements:
            if tender.requirement and parse.same_label(candidate.requirement, tender.requirement):
                line.requirement = candidate
                break
        else:
            line.requirement = next((r for r in requirements if r.position
                                     and parse.same_label(r.position, line.position)), None)
        if line.requirement and spec:
            written = {key: getattr(line.requirement, key) for key in calc.MATCH_KEYS}
            amended = calc.apply_amendments(written, amendments, spec.revision, line.requirement.requirement, scenario)
            line.attributes = {key: str(value) for key, value in amended.items()}
        for _, answer in dated:  # oldest first, so the latest answer wins per key
            for assignment in answer.assignments:
                if _canonical(assignment.position, positions) == line.position:
                    line.keys[assignment.kind] = assignment.value.strip()
        result.append(line)
    return result


def _text(value: str) -> str:
    return re.sub(r"\s+", "", value).casefold()


def _attributes(written: dict[str, str]) -> dict[str, Decimal | str] | None:
    """The five match attributes as numbers and normalised text; None when one is missing or unreadable."""
    attributes: dict[str, Decimal | str] = {}
    for key in calc.MATCH_KEYS:
        value = written.get(key, "").strip()
        if not value:
            return None
        try:
            attributes[key] = parse.number(value) if key in NUMERIC else _text(value)
        except parse.ParseError:
            return None
    return attributes


def needs_reserve(line: Line) -> bool:
    return bool(line.requirement and line.requirement.stroke_is_usable_travel)


def requirement_attributes(line: Line, revision: str, reserves: list[evidence.Reserve] | None,
                           notes: list[str]) -> dict[str, Decimal | str] | None:
    """Rule 20: what the ERP material has to equal; None when the requirement cannot be established."""
    attributes = _attributes(line.attributes)
    if attributes is None:
        notes.append(f"{line.position}: requirement incomplete")
        return None
    if not needs_reserve(line):
        return attributes
    wanted = line.requirement.reserve_key if line.requirement else ""
    fitting = [r for r in reserves or [] if not r.revision or parse.same_label(r.revision, revision)]
    by_key = [r for r in fitting if wanted and r.key and parse.same_label(r.key, wanted)]
    chosen = by_key or (fitting if len(fitting) == 1 else [])
    if not chosen:
        notes.append(f"{line.position}: no end reserve found for the usable travel")
        return None
    try:
        attributes["stroke"] = calc.nominal_stroke(Decimal(attributes["stroke"]), parse.number(chosen[0].reserve_per_end))
    except parse.ParseError:
        notes.append(f"{line.position}: end reserve {chosen[0].reserve_per_end!r} not readable")
        return None
    return attributes


# ---------------------------------------------------------------- material


def choose(requirement: dict[str, Decimal | str], candidates: list[evidence.Candidate]
           ) -> tuple[evidence.Candidate | None, str]:
    """Rule 3: the active material equal to the requirement in all five attributes.

    Returns the material and "match", or None with "none" (every candidate was read in full and none fits or the
    fitting ones are blocked) or "unknown" (the candidates could not be read well enough to say).
    """
    parsed = [(c.material_number, _attributes({k: getattr(c, k) for k in calc.MATCH_KEYS})) for c in candidates]
    hits = set(calc.matching_materials(requirement, [(number, attrs) for number, attrs in parsed if attrs]))
    fitting = [c for c in candidates if c.material_number in hits]
    for wanted in ("active", "unknown"):
        usable = [c for c in fitting if c.usable == wanted]
        if usable:
            return usable[0], "match"
    if fitting:  # equal, but blocked
        return None, "none"
    if candidates and all(attrs for _, attrs in parsed):
        return None, "none"
    return None, "unknown"


def _whole(text: str) -> int | None:
    try:
        return parse.whole(text)
    except parse.ParseError:
        return None


def _number(text: str) -> Decimal | None:
    try:
        return parse.number(text)
    except parse.ParseError:
        return None


def _day(text: str, year: int) -> date | None:
    try:
        return parse.when(text, year).date()
    except parse.ParseError:
        return None


def material(facts: evidence.MaterialFacts, number: str, notes: list[str]) -> calc.Material | None:
    """The ERP facts as calc's Material; None when not even a lead time is known."""
    stock_weeks, production_weeks = _whole(facts.stock_lead_time_weeks), _whole(facts.production_lead_time_weeks)
    if stock_weeks is None and production_weeks is None:
        notes.append(f"{number}: no lead time found")
        return None
    return calc.Material(
        material_number=number, free_stock=_whole(facts.free_stock) or 0,
        stock_lead_time_weeks=stock_weeks if stock_weeks is not None else production_weeks,
        production_lead_time_weeks=production_weeks if production_weeks is not None else stock_weeks,
        pieces_per_carton=_whole(facts.pieces_per_carton) or None,
        allocation_mass=_number(facts.allocation_mass) or Decimal(0),
        surcharge_mass=_number(facts.surcharge_mass) or Decimal(0),
        metal_index=facts.metal_index.strip() or None)


def conditions(facts: evidence.MaterialFacts, scenario: date, notes: list[str]) -> list[calc.PriceCondition]:
    result = []
    for record in facts.conditions:
        start = _day(record.valid_from, scenario.year)
        scales = [(_whole(s.min_quantity), _number(s.price)) for s in record.scales]
        if start is None or not scales or any(q is None or p is None for q, p in scales):
            notes.append(f"{facts.material_number}: a price condition from {record.valid_from!r} is not readable")
            continue
        result.append(calc.PriceCondition(
            valid_from=start, valid_to=_day(record.valid_to, scenario.year) if record.valid_to.strip() else None,
            currency=(re.search(r"[A-Za-z]{3}", record.currency) or re.search("EUR", "EUR")).group().upper(),
            fx_key=record.fx_key.strip() or None, price_unit=_whole(record.price_unit) or 1,
            scales=[calc.PriceScale(min_quantity=q, price=p) for q, p in scales]))
    return result


# ---------------------------------------------------------------- mail records


def governing[M: evidence.Mail](mails: list[M], reference: str, scenario: date, sender_local: str,
                                bidder_domain: str, key: str = "") -> M | None:
    """Rule 21: the latest message for the exact reference from the authorised sender, dated no later than the
    scenario date. With `key`, only messages that give a value for that key count."""
    by_record = {}
    for mail in mails:
        sender = parse.email(mail.sender)
        if key and mail.keys and not any(parse.same_label(key, k) for k in mail.keys):
            continue
        try:
            record = calc.DatedRecord(reference=mail.reference, sender=sender, date=parse.when(mail.date, scenario.year))
        except parse.ParseError:
            continue
        by_record[id(record)] = (record, mail)
    domain = bidder_domain.strip().casefold()
    if not domain:  # the mailbox address is unknown: take the domain most senders with this local part use
        domains = [r.sender.split("@", 1)[1] for r, _ in by_record.values()
                   if r.sender.startswith(sender_local.casefold() + "@")]
        domain = max(set(domains), key=domains.count) if domains else ""
    chosen = calc.latest_authoritative([r for r, _ in by_record.values()], reference, scenario, sender_local, domain)
    return by_record[id(chosen)][1] if chosen else None


def approval(mail: evidence.ApprovalMail | None, notes: list[str]) -> calc.Approval | None:
    if mail is None:
        return None
    percent = _number(mail.percent)
    if percent is None:
        notes.append(f"approval percent {mail.percent!r} not readable")
        return None
    threshold = _number(mail.min_order_value) if mail.min_order_value.strip() else None
    return calc.Approval(percent=percent, min_order_value=threshold)


@dataclass
class Records:
    """What the governing messages say; a part is None when it was not needed or not found."""

    approval: calc.Approval | None = None
    rules: list[evidence.ConditionRule] | None = None
    tariffs: list[evidence.Tariff] | None = None
    commitments: list[evidence.Commitment] | None = None
    pools: list[evidence.Pool] | None = None
    bonuses: list[evidence.Bonus] | None = None
    fx: list[evidence.FxRate] | None = None
    indices: list[evidence.Index] | None = None


def _one[R](records: list[R] | None, wanted: str, name=lambda r: r.key) -> R | None:
    """The record for a key: the one written the same way, else the only one there is."""
    records = records or []
    for record in records:
        if wanted and name(record) and parse.same_label(name(record), wanted):
            return record
    return records[0] if len(records) == 1 else None


# ---------------------------------------------------------------- the plan


class Entry(BaseModel):
    """One position as it goes into the bid form."""
    position: str
    material_number: str
    attributes: dict[str, str] = Field(default_factory=dict, description="As the ERP writes them")
    quantity: int
    unit_price: Decimal | None = None
    lead_time_weeks: int | None = None
    base_unit_price: Decimal | None = None
    surcharge_per_unit: Decimal | None = None
    packaging_per_unit: Decimal | None = None
    rebate_total: Decimal | None = None


class Plan(BaseModel):
    reference: str
    decision: str
    discount_percent: Decimal = Decimal(0)
    entries: list[Entry] = Field(default_factory=list)
    omitted: list[str] = Field(default_factory=list)
    notes: list[str] = Field(default_factory=list)

    def total(self, positions: list[str] | None = None) -> Decimal:
        """Rule 7: the sum of quantity x rounded unit price over the positions entered (all of them by default)."""
        entered = [e for e in self.entries if positions is None
                   or any(parse.same_label(e.position, p) for p in positions)]
        return calc.money(sum((e.quantity * (e.unit_price or Decimal(0)) for e in entered), Decimal(0)))

    def table(self) -> str:
        """The positions as text for the worker that fills the form, numbers in German format."""
        rows = []
        for e in self.entries:
            shown = ", ".join(f"{key} {value}" for key, value in e.attributes.items() if value)
            row = [f"Position {e.position}: material {e.material_number}" + (f" ({shown})" if shown else ""),
                   f"quantity {e.quantity} pieces"]
            if e.unit_price is None:
                row.append("net unit price 0,00 (not established); leave the calculation breakdown fields empty")
            else:
                row.append(f"net unit price {parse.german(e.unit_price)}")
            row.append(f"delivery time {e.lead_time_weeks} weeks" if e.lead_time_weeks is not None
                       else "delivery time not established: choose the longest one the form offers")
            parts = [("base price per piece", e.base_unit_price), ("surcharge per piece", e.surcharge_per_unit),
                     ("packaging per piece", e.packaging_per_unit), ("project bonus for the whole position",
                                                                     e.rebate_total)]
            if e.unit_price is not None:
                row.append("calculation breakdown: " + ", ".join(
                    f"{name} {parse.german(value)}" for name, value in parts if value is not None))
            rows.append("; ".join(row))
        return "\n".join(rows)


def _position_input(line: Line, pieces: int, chosen: calc.Material, prices: list[calc.PriceCondition],
                    records: Records, notes: list[str]) -> calc.PositionInput:
    """Rules 12, 23, 24 and the ordinary setup fee for one position; a key without its record is noted and left out."""
    keys = line.keys
    scope = calc.DiscountScope.BASE_ONLY
    if keys.get("condition_group"):
        rule = _one(records.rules, keys["condition_group"], lambda r: r.group)
        if rule:
            scope = calc.DiscountScope(rule.scope)
        else:
            notes.append(f"{line.position}: no rule for condition group {keys['condition_group']!r}; default used")
    fee = Decimal(0)
    if keys.get("setup_fee"):
        fee = _number(keys["setup_fee"]) or Decimal(0)
    packaging = None
    if keys.get("packaging_tariff"):
        tariff = _one(records.tariffs, keys["packaging_tariff"])
        price = _number(tariff.price_per_carton) if tariff else None
        if price is not None and chosen.pieces_per_carton:
            packaging = calc.PackagingTariff(price_per_carton=price)
        else:
            notes.append(f"{line.position}: packaging tariff {keys['packaging_tariff']!r} or carton size not found")
    commitment = None
    if keys.get("delivery_commitment"):
        found = _one(records.commitments, keys["delivery_commitment"])
        ceiling, weeks = (_whole(found.ceiling), _whole(found.lead_time_weeks)) if found else (None, None)
        if found and ceiling is not None and weeks is not None:
            number = chosen.material_number if parse.same_label(found.material_number, chosen.material_number) \
                else found.material_number.strip()
            commitment = calc.DeliveryCommitment(material_number=number, ceiling=ceiling, lead_time_weeks=weeks)
        else:
            notes.append(f"{line.position}: delivery commitment {keys['delivery_commitment']!r} not found")
    return calc.PositionInput(position=line.position, quantity=pieces, material=chosen, conditions=prices,
                              discount_scope=scope, setup_fee=fee, packaging=packaging, commitment=commitment)


def _fx(inputs: list[calc.PositionInput], scenario: date, records: Records, notes: list[str]) -> dict[str, Decimal]:
    """Rule 22: EUR per currency unit for every key the valid conditions name."""
    rates: dict[str, Decimal] = {}
    for position in inputs:
        try:
            condition = calc.valid_condition(position.conditions, scenario)
        except calc.CalcError:
            continue
        if condition.currency == "EUR":
            continue
        key = condition.fx_key or condition.currency
        found = _one(records.fx, key) or _one(records.fx, condition.currency, lambda r: r.currency)
        rate = _number(found.rate) if found else None
        if not rate:
            notes.append(f"{position.position}: no exchange rate for {key!r}")
            continue
        rates[key] = rate if found.quoted_as == "eur_per_unit" else Decimal(1) / rate
    return rates


def _indices(inputs: list[calc.PositionInput], scenario: date, records: Records) -> dict[str, list[calc.MetalIndexRate]]:
    """Rule 28: every listed rate with its window, under the code the materials use."""
    result: dict[str, list[calc.MetalIndexRate]] = {}
    codes = {p.material.metal_index for p in inputs if p.material and p.material.metal_index}
    for index in records.indices or []:
        rates = [calc.MetalIndexRate(rate=rate, valid_from=_day(r.valid_from, scenario.year) if r.valid_from else None,
                                     valid_to=_day(r.valid_to, scenario.year) if r.valid_to else None)
                 for r in index.rates if (rate := _number(r.rate)) is not None]
        if rates:
            result[_canonical(index.code, sorted(codes))] = rates
    return result


def _priceable(position: calc.PositionInput, bid: calc.BidInput) -> bool:
    try:
        calc._base_eur(position, position.quantity, bid)
        return position.quantity > 0
    except calc.CalcError:
        return False


def _calculate(bid: calc.BidInput, notes: list[str]) -> calc.BidResult | None:
    """calc on the full facts; when a part is contradictory, leave that part out and try again."""
    def without_metal(b: calc.BidInput) -> calc.BidInput:
        positions = [p.model_copy(update={"material": p.material.model_copy(update={"surcharge_mass": Decimal(0)})})
                     for p in b.positions]
        return b.model_copy(update={"positions": positions})

    steps = [("project bonus", lambda b: b.model_copy(update={"project_bonus": None})),
             ("setup pool", lambda b: b.model_copy(update={"setup_pool": None})),
             ("packaging", lambda b: b.model_copy(update={
                 "positions": [p.model_copy(update={"packaging": None}) for p in b.positions]})),
             ("metal surcharge", without_metal)]
    for dropped, step in [(None, None), *steps]:
        if step:
            bid = step(bid)
            notes.append(f"calculated without the {dropped}")
        try:
            return calc.calculate(bid)
        except calc.CalcError as error:
            notes.append(f"calculation: {error}")
    return None


def plan(reference: str, scenario: date, tender: list[Line], chosen: dict[str, tuple[evidence.Candidate | None, str]],
         facts: dict[str, evidence.MaterialFacts], records: Records, notes: list[str]) -> Plan:
    """Rules 3 to 8 and 15 to 28 on what was established. `chosen` maps a position to `choose`'s result, `facts` a
    material number to its ERP facts."""
    if any(verdict == "none" for _, verdict in chosen.values()):
        missing = sorted(p for p, (_, verdict) in chosen.items() if verdict == "none")
        notes.append(f"no matching active material for {', '.join(missing)}")
        return Plan(reference=reference, decision="no_bid", notes=notes,
                    discount_percent=calc.effective_discount(records.approval, None))

    result = Plan(reference=reference, decision="bid", notes=notes)
    inputs: list[calc.PositionInput] = []
    bare: list[tuple[Line, evidence.Candidate, int]] = []  # material and quantity known, nothing else
    picked: dict[str, evidence.Candidate] = {}
    for line in tender:
        candidate, _ = chosen.get(line.position, (None, "unknown"))
        pieces = line.pieces
        if candidate is None or pieces is None:
            result.omitted.append(line.position)
            continue
        picked[line.position] = candidate
        known = facts.get(candidate.material_number)
        master = material(known, candidate.material_number, notes) if known else None
        if master is None:
            bare.append((line, candidate, pieces))
            continue
        inputs.append(_position_input(line, pieces, master, conditions(known, scenario, notes), records, notes))

    by_position = {line.position: line for line in tender}
    pooled: dict[str, int] = {}
    for position in inputs:
        pooled[position.material.material_number] = pooled.get(position.material.material_number, 0) + position.quantity
    for _, candidate, pieces in bare:
        pooled[candidate.material_number] = pooled.get(candidate.material_number, 0) + pieces

    bid = calc.BidInput(tender_reference=reference, scenario_date=scenario, positions=inputs, approval=records.approval)
    bid.fx_rates = _fx(inputs, scenario, records, notes)
    bid.metal_indices = _indices(inputs, scenario, records)
    priced = [p for p in inputs if _priceable(p, bid)]
    members = {p.position for p in priced}
    pool_members = [p for p in members if by_position[p].keys.get("setup_pool")]
    if pool_members:
        pool = _one(records.pools, by_position[pool_members[0]].keys["setup_pool"])
        fee = _number(pool.fee) if pool else None
        if fee is not None:
            bid.setup_pool = calc.SetupPool(fee=fee, members=sorted(pool_members, key=calc.position_key),
                                            allocation=calc.CentAllocation(pool.allocation),
                                            tie_order=calc.TieOrder(pool.tie_order), rest_base=pool.rest_base)
        else:
            notes.append("setup pool fee not found")
    bonus_members = [p for p in members if by_position[p].keys.get("project_bonus")]
    if bonus_members:
        bonus = _one(records.bonuses, by_position[bonus_members[0]].keys["project_bonus"])
        bands = [calc.BonusBand(lower=lower, percent=percent, upper=_number(b.upper) if b.upper.strip() else None)
                 for b in (bonus.bands if bonus else [])
                 if (lower := _number(b.lower)) is not None and (percent := _number(b.percent)) is not None]
        if bands:
            bid.project_bonus = calc.ProjectBonus(bands=bands, members=sorted(bonus_members, key=calc.position_key),
                                                  include_surcharge=bonus.on_goods_and_surcharge)
        else:
            notes.append("project bonus bands not found")

    outcome = _calculate(bid.model_copy(update={"positions": priced}), notes) if priced else None
    answers = {a.position: a for a in outcome.positions} if outcome else {}
    if outcome:
        result.discount_percent = outcome.discount_percent
    else:
        result.discount_percent = calc.effective_discount(records.approval, None)

    def shown(candidate: evidence.Candidate) -> dict[str, str]:
        return {key: getattr(candidate, key) for key in calc.MATCH_KEYS}

    for position in inputs:
        candidate = picked[position.position]
        weeks = calc.lead_time(position, pooled[position.material.material_number])  # rule 15: over every position
        answer = answers.get(position.position)
        entry = Entry(position=position.position, material_number=candidate.material_number, quantity=position.quantity,
                      attributes=shown(candidate), lead_time_weeks=weeks)
        if answer:
            entry.unit_price, entry.base_unit_price = answer.unit_price, answer.base_unit_price
            entry.surcharge_per_unit, entry.packaging_per_unit = answer.surcharge_per_unit, answer.packaging_per_unit
            entry.rebate_total = answer.rebate_total
        else:
            notes.append(f"{position.position}: no price established")
        result.entries.append(entry)
    for line, candidate, pieces in bare:
        result.entries.append(Entry(position=line.position, material_number=candidate.material_number, quantity=pieces,
                                    attributes=shown(candidate)))
    result.entries.sort(key=lambda e: calc.position_key(e.position))
    return result

toolUseResult.content:
"""
From records to the bid: which record applies is decided here by the bid rules, in code; `calc` does the arithmetic.

Everything in this module is pure. It never fails as a whole: a fact that is missing or unreadable costs the
fields that depend on it and is written to `Plan.notes`, the rest of the bid is still priced.
"""
import re
from dataclasses import dataclass, field
from datetime import date, datetime
from decimal import Decimal

import calc
import evidence
import parse
from pydantic import BaseModel, Field

NUMERIC = ("bore", "stroke", "pressure")


# ---------------------------------------------------------------- tender, clarifications, specification


@dataclass
class Line:
    """One tender position with what the tender, its clarifications and the specification say about it."""

    position: str
    quantity: int | None = None  # final quantity in the stated unit
    unit: calc.Unit = calc.Unit.PIECE
    requirement: evidence.Requirement | None = None
    attributes: dict[str, str] = field(default_factory=dict)  # the five match attributes after amendments, as written
    keys: dict[str, str] = field(default_factory=dict)  # assignment kind -> value from the clarifications

    @property
    def group(self) -> str:
        return self.requirement.catalogue_group.strip() if self.requirement else ""

    @property
    def pieces(self) -> int | None:
        if self.quantity is None:
            return None
        per_set = None
        if self.requirement and self.requirement.pieces_per_set:
            try:
                per_set = parse.whole(self.requirement.pieces_per_set)
            except parse.ParseError:
                per_set = None
        try:
            return calc.to_pieces(self.quantity, self.unit, per_set)
        except calc.CalcError:
            return None


def _canonical(written: str, known: list[str]) -> str:
    """The entry of `known` that `written` means, else `written` itself."""
    for candidate in known:
        if parse.same_label(written, candidate):
            return candidate
    return written.strip()


def _dated(answers: list[evidence.Clarification], scenario: date, notes: list[str]
           ) -> list[tuple[datetime, evidence.Clarification]]:
    """The answers given no later than the scenario date, oldest first."""
    dated = []
    for answer in answers:
        try:
            given = parse.when(answer.date, scenario.year)
        except parse.ParseError:
            notes.append(f"clarification {answer.number}: date {answer.date!r} not readable, ignored")
            continue
        if given.date() <= scenario:
            dated.append((given, answer))
    return sorted(dated, key=lambda pair: (pair[0], calc.position_key(pair[1].number)))


def lines(sheet: evidence.TenderSheet, clarifications: evidence.Clarifications | None,
          spec: evidence.SpecSheet | None, scenario: date, notes: list[str]) -> list[Line]:
    """Rules 1, 2, 13, 14 and 17: final quantities, the governing requirement with its amendments, and the keys."""
    positions = [p.position.strip() for p in sheet.positions]
    requirements = spec.requirements if spec else []
    dated = _dated(clarifications.answers, scenario, notes) if clarifications else []
    numbers = [answer.number for _, answer in dated]
    withdrawn = {_canonical(w, numbers) for _, answer in dated for w in answer.withdraws}

    changes, amendments = [], []
    for given, answer in dated:
        for change in answer.quantity_changes:
            try:
                changes.append(calc.QuantityChange(number=answer.number, date=given, quantity=parse.whole(change.quantity),
                                                   position=_canonical(change.position, positions)))
            except parse.ParseError:
                notes.append(f"clarification {answer.number}: quantity {change.quantity!r} not readable")
        for amendment in answer.amendments:
            if amendment.attribute in calc.MATCH_KEYS and spec:
                amendments.append(calc.Amendment(
                    date=given, revision=_canonical(amendment.revision, [spec.revision]),
                    requirement=_canonical(amendment.requirement, [r.requirement for r in requirements]),
                    attributes={amendment.attribute: amendment.value}))

    result = []
    for tender in sheet.positions:
        line = Line(position=tender.position.strip())
        try:
            line.unit = calc.parse_unit(tender.unit)
        except calc.CalcError:
            notes.append(f"{line.position}: unit {tender.unit!r} unknown, taken as pieces")
        try:
            line.quantity = calc.resolve_quantity(parse.whole(tender.quantity), line.position, changes, withdrawn,
                                                  scenario)
        except parse.ParseError:
            notes.append(f"{line.position}: quantity {tender.quantity!r} not readable")
        for candidate in requirements:
            if tender.requirement and parse.same_label(candidate.requirement, tender.requirement):
                line.requirement = candidate
                break
        else:
            line.requirement = next((r for r in requirements if r.position
                                     and parse.same_label(r.position, line.position)), None)
        if line.requirement and spec:
            written = {key: getattr(line.requirement, key) for key in calc.MATCH_KEYS}
            amended = calc.apply_amendments(written, amendments, spec.revision, line.requirement.requirement, scenario)
            line.attributes = {key: str(value) for key, value in amended.items()}
        for _, answer in dated:  # oldest first, so the latest answer wins per key
            for assignment in answer.assignments:
                if _canonical(assignment.position, positions) == line.position:
                    line.keys[assignment.kind] = assignment.value.strip()
        result.append(line)
    return result


def _text(value: str) -> str:
    return re.sub(r"\s+", "", value).casefold()


def _attributes(written: dict[str, str]) -> dict[str, Decimal | str] | None:
    """The five match attributes as numbers and normalised text; None when one is missing or unreadable."""
    attributes: dict[str, Decimal | str] = {}
    for key in calc.MATCH_KEYS:
        value = written.get(key, "").strip()
        if not value:
            return None
        try:
            attributes[key] = parse.number(value) if key in NUMERIC else _text(value)
        except parse.ParseError:
            return None
    return attributes


def needs_reserve(line: Line) -> bool:
    return bool(line.requirement and line.requirement.stroke_is_usable_travel)


def requirement_attributes(line: Line, revision: str, reserves: list[evidence.Reserve] | None,
                           notes: list[str]) -> dict[str, Decimal | str] | None:
    """Rule 20: what the ERP material has to equal; None when the requirement cannot be established."""
    attributes = _attributes(line.attributes)
    if attributes is None:
        notes.append(f"{line.position}: requirement incomplete")
        return None
    if not needs_reserve(line):
        return attributes
    wanted = line.requirement.reserve_key if line.requirement else ""
    fitting = [r for r in reserves or [] if not r.revision or parse.same_label(r.revision, revision)]
    by_key = [r for r in fitting if wanted and r.key and parse.same_label(r.key, wanted)]
    chosen = by_key or (fitting if len(fitting) == 1 else [])
    if not chosen:
        notes.append(f"{line.position}: no end reserve found for the usable travel")
        return None
    try:
        attributes["stroke"] = calc.nominal_stroke(Decimal(attributes["stroke"]), parse.number(chosen[0].reserve_per_end))
    except parse.ParseError:
        notes.append(f"{line.position}: end reserve {chosen[0].reserve_per_end!r} not readable")
        return None
    return attributes


# ---------------------------------------------------------------- material


def choose(requirement: dict[str, Decimal | str], candidates: list[evidence.Candidate]
           ) -> tuple[evidence.Candidate | None, str]:
    """Rule 3: the active material equal to the requirement in all five attributes.

    Returns the material and "match", or None with "none" (every candidate was read in full and none fits or the
    fitting ones are blocked) or "unknown" (the candidates could not be read well enough to say).
    """
    parsed = [(c.material_number, _attributes({k: getattr(c, k) for k in calc.MATCH_KEYS})) for c in candidates]
    hits = set(calc.matching_materials(requirement, [(number, attrs) for number, attrs in parsed if attrs]))
    fitting = [c for c in candidates if c.material_number in hits]
    for wanted in ("active", "unknown"):
        usable = [c for c in fitting if c.usable == wanted]
        if usable:
            return usable[0], "match"
    if fitting:  # equal, but blocked
        return None, "none"
    if candidates and all(attrs for _, attrs in parsed):
        return None, "none"
    return None, "unknown"


def _whole(text: str) -> int | None:
    try:
        return parse.whole(text)
    except parse.ParseError:
        return None


def _number(text: str) -> Decimal | None:
    try:
        return parse.number(text)
    except parse.ParseError:
        return None


def _day(text: str, year: int) -> date | None:
    try:
        return parse.when(text, year).date()
    except parse.ParseError:
        return None


def material(facts: evidence.MaterialFacts, number: str, notes: list[str]) -> calc.Material | None:
    """The ERP facts as calc's Material; None when not even a lead time is known."""
    stock_weeks, production_weeks = _whole(facts.stock_lead_time_weeks), _whole(facts.production_lead_time_weeks)
    if stock_weeks is None and production_weeks is None:
        notes.append(f"{number}: no lead time found")
        return None
    return calc.Material(
        material_number=number, free_stock=_whole(facts.free_stock) or 0,
        stock_lead_time_weeks=stock_weeks if stock_weeks is not None else production_weeks,
        production_lead_time_weeks=production_weeks if production_weeks is not None else stock_weeks,
        pieces_per_carton=_whole(facts.pieces_per_carton) or None,
        allocation_mass=_number(facts.allocation_mass) or Decimal(0),
        surcharge_mass=_number(facts.surcharge_mass) or Decimal(0),
        metal_index=facts.metal_index.strip() or None)


def conditions(facts: evidence.MaterialFacts, scenario: date, notes: list[str]) -> list[calc.PriceCondition]:
    result = []
    for record in facts.conditions:
        start = _day(record.valid_from, scenario.year)
        scales = [(_whole(s.min_quantity), _number(s.price)) for s in record.scales]
        if start is None or not scales or any(q is None or p is None for q, p in scales):
            notes.append(f"{facts.material_number}: a price condition from {record.valid_from!r} is not readable")
            continue
        result.append(calc.PriceCondition(
            valid_from=start, valid_to=_day(record.valid_to, scenario.year) if record.valid_to.strip() else None,
            currency=(re.search(r"[A-Za-z]{3}", record.currency) or re.search("EUR", "EUR")).group().upper(),
            fx_key=record.fx_key.strip() or None, price_unit=_whole(record.price_unit) or 1,
            scales=[calc.PriceScale(min_quantity=q, price=p) for q, p in scales]))
    return result


# ---------------------------------------------------------------- mail records


def governing[M: evidence.Mail](mails: list[M], reference: str, scenario: date, sender_local: str,
                                bidder_domain: str, key: str = "") -> M | None:
    """Rule 21: the latest message for the exact reference from the authorised sender, dated no later than the
    scenario date. With `key`, only messages that give a value for that key count."""
    by_record = {}
    for mail in mails:
        sender = parse.email(mail.sender)
        if key and mail.keys and not any(parse.same_label(key, k) for k in mail.keys):
            continue
        try:
            record = calc.DatedRecord(reference=mail.reference, sender=sender, date=parse.when(mail.date, scenario.year))
        except parse.ParseError:
            continue
        by_record[id(record)] = (record, mail)
    domain = bidder_domain.strip().casefold()
    if not domain:  # the mailbox address is unknown: take the domain most senders with this local part use
        domains = [r.sender.split("@", 1)[1] for r, _ in by_record.values()
                   if r.sender.startswith(sender_local.casefold() + "@")]
        domain = max(set(domains), key=domains.count) if domains else ""
    chosen = calc.latest_authoritative([r for r, _ in by_record.values()], reference, scenario, sender_local, domain)
    return by_record[id(chosen)][1] if chosen else None


def approval(mail: evidence.ApprovalMail | None, notes: list[str]) -> calc.Approval | None:
    if mail is None:
        return None
    percent = _number(mail.percent)
    if percent is None:
        notes.append(f"approval percent {mail.percent!r} not readable")
        return None
    threshold = _number(mail.min_order_value) if mail.min_order_value.strip() else None
    return calc.Approval(percent=percent, min_order_value=threshold)


@dataclass
class Records:
    """What the governing messages say; a part is None when it was not needed or not found."""

    approval: calc.Approval | None = None
    rules: list[evidence.ConditionRule] | None = None
    tariffs: list[evidence.Tariff] | None = None
    commitments: list[evidence.Commitment] | None = None
    pools: list[evidence.Pool] | None = None
    bonuses: list[evidence.Bonus] | None = None
    fx: list[evidence.FxRate] | None = None
    indices: list[evidence.Index] | None = None


def _one[R](records: list[R] | None, wanted: str, name=lambda r: r.key) -> R | None:
    """The record for a key: the one written the same way, else the only one there is."""
    records = records or []
    for record in records:
        if wanted and name(record) and parse.same_label(name(record), wanted):
            return record
    return records[0] if len(records) == 1 else None


# ---------------------------------------------------------------- the plan


class Entry(BaseModel):
    """One position as it goes into the bid form."""
    position: str
    material_number: str
    attributes: dict[str, str] = Field(default_factory=dict, description="As the ERP writes them")
    quantity: int
    unit_price: Decimal | None = None
    lead_time_weeks: int | None = None
    base_unit_price: Decimal | None = None
    surcharge_per_unit: Decimal | None = None
    packaging_per_unit: Decimal | None = None
    rebate_total: Decimal | None = None


class Plan(BaseModel):
    reference: str
    decision: str
    discount_percent: Decimal = Decimal(0)
    entries: list[Entry] = Field(default_factory=list)
    omitted: list[str] = Field(default_factory=list)
    notes: list[str] = Field(default_factory=list)

    def total(self, positions: list[str] | None = None) -> Decimal:
        """Rule 7: the sum of quantity x rounded unit price over the positions entered (all of them by default)."""
        entered = [e for e in self.entries if positions is None
                   or any(parse.same_label(e.position, p) for p in positions)]
        return calc.money(sum((e.quantity * (e.unit_price or Decimal(0)) for e in entered), Decimal(0)))

    def table(self) -> str:
        """The positions as text for the worker that fills the form, numbers in German format."""
        rows = []
        for e in self.entries:
            shown = ", ".join(f"{key} {value}" for key, value in e.attributes.items() if value)
            row = [f"Position {e.position}: material {e.material_number}" + (f" ({shown})" if shown else ""),
                   f"quantity {e.quantity} pieces"]
            if e.unit_price is None:
                row.append("net unit price 0,00 (not established); leave the calculation breakdown fields empty")
            else:
                row.append(f"net unit price {parse.german(e.unit_price)}")
            row.append(f"delivery time {e.lead_time_weeks} weeks" if e.lead_time_weeks is not None
                       else "delivery time not established: choose the longest one the form offers")
            parts = [("base price per piece", e.base_unit_price), ("surcharge per piece", e.surcharge_per_unit),
                     ("packaging per piece", e.packaging_per_unit), ("project bonus for the whole position",
                                                                     e.rebate_total)]
            if e.unit_price is not None:
                row.append("calculation breakdown: " + ", ".join(
                    f"{name} {parse.german(value)}" for name, value in parts if value is not None))
            rows.append("; ".join(row))
        return "\n".join(rows)


def _position_input(line: Line, pieces: int, chosen: calc.Material, prices: list[calc.PriceCondition],
                    records: Records, notes: list[str]) -> calc.PositionInput:
    """Rules 12, 23, 24 and the ordinary setup fee for one position; a key without its record is noted and left out."""
    keys = line.keys
    scope = calc.DiscountScope.BASE_ONLY
    if keys.get("condition_group"):
        rule = _one(records.rules, keys["condition_group"], lambda r: r.group)
        if rule:
            scope = calc.DiscountScope(rule.scope)
        else:
            notes.append(f"{line.position}: no rule for condition group {keys['condition_group']!r}; default used")
    fee = Decimal(0)
    if keys.get("setup_fee"):
        fee = _number(keys["setup_fee"]) or Decimal(0)
    packaging = None
    if keys.get("packaging_tariff"):
        tariff = _one(records.tariffs, keys["packaging_tariff"])
        price = _number(tariff.price_per_carton) if tariff else None
        if price is not None and chosen.pieces_per_carton:
            packaging = calc.PackagingTariff(price_per_carton=price)
        else:
            notes.append(f"{line.position}: packaging tariff {keys['packaging_tariff']!r} or carton size not found")
    commitment = None
    if keys.get("delivery_commitment"):
        found = _one(records.commitments, keys["delivery_commitment"])
        ceiling, weeks = (_whole(found.ceiling), _whole(found.lead_time_weeks)) if found else (None, None)
        if found and ceiling is not None and weeks is not None:
            number = chosen.material_number if parse.same_label(found.material_number, chosen.material_number) \
                else found.material_number.strip()
            commitment = calc.DeliveryCommitment(material_number=number, ceiling=ceiling, lead_time_weeks=weeks)
        else:
            notes.append(f"{line.position}: delivery commitment {keys['delivery_commitment']!r} not found")
    return calc.PositionInput(position=line.position, quantity=pieces, material=chosen, conditions=prices,
                              discount_scope=scope, setup_fee=fee, packaging=packaging, commitment=commitment)


def _fx(inputs: list[calc.PositionInput], scenario: date, records: Records, notes: list[str]) -> dict[str, Decimal]:
    """Rule 22: EUR per currency unit for every key the valid conditions name."""
    rates: dict[str, Decimal] = {}
    for position in inputs:
        try:
            condition = calc.valid_condition(position.conditions, scenario)
        except calc.CalcError:
            continue
        if condition.currency == "EUR":
            continue
        key = condition.fx_key or condition.currency
        found = _one(records.fx, key) or _one(records.fx, condition.currency, lambda r: r.currency)
        rate = _number(found.rate) if found else None
        if not rate:
            notes.append(f"{position.position}: no exchange rate for {key!r}")
            continue
        rates[key] = rate if found.quoted_as == "eur_per_unit" else Decimal(1) / rate
    return rates


def _indices(inputs: list[calc.PositionInput], scenario: date, records: Records) -> dict[str, list[calc.MetalIndexRate]]:
    """Rule 28: every listed rate with its window, under the code the materials use."""
    result: dict[str, list[calc.MetalIndexRate]] = {}
    codes = {p.material.metal_index for p in inputs if p.material and p.material.metal_index}
    for index in records.indices or []:
        rates = [calc.MetalIndexRate(rate=rate, valid_from=_day(r.valid_from, scenario.year) if r.valid_from else None,
                                     valid_to=_day(r.valid_to, scenario.year) if r.valid_to else None)
                 for r in index.rates if (rate := _number(r.rate)) is not None]
        if rates:
            result[_canonical(index.code, sorted(codes))] = rates
    return result


def _priceable(position: calc.PositionInput, bid: calc.BidInput) -> bool:
    try:
        calc._base_eur(position, position.quantity, bid)
        return position.quantity > 0
    except calc.CalcError:
        return False


def _calculate(bid: calc.BidInput, notes: list[str]) -> calc.BidResult | None:
    """calc on the full facts; when a part is contradictory, leave that part out and try again."""
    def without_metal(b: calc.BidInput) -> calc.BidInput:
        positions = [p.model_copy(update={"material": p.material.model_copy(update={"surcharge_mass": Decimal(0)})})
                     for p in b.positions]
        return b.model_copy(update={"positions": positions})

    steps = [("project bonus", lambda b: b.model_copy(update={"project_bonus": None})),
             ("setup pool", lambda b: b.model_copy(update={"setup_pool": None})),
             ("packaging", lambda b: b.model_copy(update={
                 "positions": [p.model_copy(update={"packaging": None}) for p in b.positions]})),
             ("metal surcharge", without_metal)]
    for dropped, step in [(None, None), *steps]:
        if step:
            bid = step(bid)
            notes.append(f"calculated without the {dropped}")
        try:
            return calc.calculate(bid)
        except calc.CalcError as error:
            notes.append(f"calculation: {error}")
    return None


def plan(reference: str, scenario: date, tender: list[Line], chosen: dict[str, tuple[evidence.Candidate | None, str]],
         facts: dict[str, evidence.MaterialFacts], records: Records, notes: list[str]) -> Plan:
    """Rules 3 to 8 and 15 to 28 on what was established. `chosen` maps a position to `choose`'s result, `facts` a
    material number to its ERP facts."""
    if any(verdict == "none" for _, verdict in chosen.values()):
        missing = sorted(p for p, (_, verdict) in chosen.items() if verdict == "none")
        notes.append(f"no matching active material for {', '.join(missing)}")
        return Plan(reference=reference, decision="no_bid", notes=notes,
                    discount_percent=calc.effective_discount(records.approval, None))

    result = Plan(reference=reference, decision="bid", notes=notes)
    inputs: list[calc.PositionInput] = []
    bare: list[tuple[Line, evidence.Candidate, int]] = []  # material and quantity known, nothing else
    picked: dict[str, evidence.Candidate] = {}
    for line in tender:
        candidate, _ = chosen.get(line.position, (None, "unknown"))
        pieces = line.pieces
        if candidate is None or pieces is None:
            result.omitted.append(line.position)
            continue
        picked[line.position] = candidate
        known = facts.get(candidate.material_number)
        master = material(known, candidate.material_number, notes) if known else None
        if master is None:
            bare.append((line, candidate, pieces))
            continue
        inputs.append(_position_input(line, pieces, master, conditions(known, scenario, notes), records, notes))

    by_position = {line.position: line for line in tender}
    pooled: dict[str, int] = {}
    for position in inputs:
        pooled[position.material.material_number] = pooled.get(position.material.material_number, 0) + position.quantity
    for _, candidate, pieces in bare:
        pooled[candidate.material_number] = pooled.get(candidate.material_number, 0) + pieces

    bid = calc.BidInput(tender_reference=reference, scenario_date=scenario, positions=inputs, approval=records.approval)
    bid.fx_rates = _fx(inputs, scenario, records, notes)
    bid.metal_indices = _indices(inputs, scenario, records)
    priced = [p for p in inputs if _priceable(p, bid)]
    members = {p.position for p in priced}
    pool_members = [p for p in members if by_position[p].keys.get("setup_pool")]
    if pool_members:
        pool = _one(records.pools, by_position[pool_members[0]].keys["setup_pool"])
        fee = _number(pool.fee) if pool else None
        if fee is not None:
            bid.setup_pool = calc.SetupPool(fee=fee, members=sorted(pool_members, key=calc.position_key),
                                            allocation=calc.CentAllocation(pool.allocation),
                                            tie_order=calc.TieOrder(pool.tie_order), rest_base=pool.rest_base)
        else:
            notes.append("setup pool fee not found")
    bonus_members = [p for p in members if by_position[p].keys.get("project_bonus")]
    if bonus_members:
        bonus = _one(records.bonuses, by_position[bonus_members[0]].keys["project_bonus"])
        bands = [calc.BonusBand(lower=lower, percent=percent, upper=_number(b.upper) if b.upper.strip() else None)
                 for b in (bonus.bands if bonus else [])
                 if (lower := _number(b.lower)) is not None and (percent := _number(b.percent)) is not None]
        if bands:
            bid.project_bonus = calc.ProjectBonus(bands=bands, members=sorted(bonus_members, key=calc.position_key),
                                                  include_surcharge=bonus.on_goods_and_surcharge)
        else:
            notes.append("project bonus bands not found")

    outcome = _calculate(bid.model_copy(update={"positions": priced}), notes) if priced else None
    answers = {a.position: a for a in outcome.positions} if outcome else {}
    if outcome:
        result.discount_percent = outcome.discount_percent
    else:
        result.discount_percent = calc.effective_discount(records.approval, None)

    def shown(candidate: evidence.Candidate) -> dict[str, str]:
        return {key: getattr(candidate, key) for key in calc.MATCH_KEYS}

    for position in inputs:
        candidate = picked[position.position]
        weeks = calc.lead_time(position, pooled[position.material.material_number])  # rule 15: over every position
        answer = answers.get(position.position)
        entry = Entry(position=position.position, material_number=candidate.material_number, quantity=position.quantity,
                      attributes=shown(candidate), lead_time_weeks=weeks)
        if answer:
            entry.unit_price, entry.base_unit_price = answer.unit_price, answer.base_unit_price
            entry.surcharge_per_unit, entry.packaging_per_unit = answer.surcharge_per_unit, answer.packaging_per_unit
            entry.rebate_total = answer.rebate_total
        else:
            notes.append(f"{position.position}: no price established")
        result.entries.append(entry)
    for line, candidate, pieces in bare:
        result.entries.append(Entry(position=line.position, material_number=candidate.material_number, quantity=pieces,
                                    attributes=shown(candidate)))
    result.entries.sort(key=lambda e: calc.position_key(e.position))
    return result

