async function pollDevice(api, device, signal) {
  let wait = Math.max(1, Number(device.interval) || 5) * 1000
  for (;;) {
    await sleep(wait, signal)
    if (signal?.aborted) return null
    const response = await send(api, "POST", "/v1/cli/token", { body: { device_code: device.device_code } })
    if (signal?.aborted) return null
    if (response.ok) return response.json()
    if (response.status === 429) {
      wait += 5000
      continue
    }
    const text = await response.text().catch(() => "")
    let body = {}
    try {
      body = JSON.parse(text)
    } catch {}
    const interval = Number(body?.interval) * 1000 || 0
    switch (body?.error?.type) {
      case "authorization_pending":
        wait = Math.max(wait, interval)
        continue
      case "slow_down":
        wait = Math.max(wait + 5000, interval)
        continue
      case "access_denied":
        throw new CliError(EXIT.auth, "Sign-in was cancelled in the browser.", 400)
      case "expired_token":
        throw new CliError(EXIT.auth, "The code expired before it was approved. Run `atira login` again.", 400)
      default:
        throw await responseError(response, text)
    }

